// Plan H8, measured with a throwaway stub of the column (Fixed, 10, Optional,
// after ID): at 100 it costs Model; at 80 it costs Duration AND Tools (the plan
// said Duration only); at 60 it is gone and the five DEVDESK-43 columns remain.
// Est. cost is the last optional column to go, after State.
func TestEstCostLayoutAtEachWidth(t *testing.T) {
	tests := []struct {
		width int
		want  []string
	}{
		{200, []string{"Agent", "ID", costTitle, "State", "Tools", "Duration", "Model", "In", "Out", "Cache read", "Cache write", "Total", "Share"}},
		{100, []string{"Agent", "ID", costTitle, "State", "Tools", "Duration", "Out", "Total", "Share"}}, // loses Model
		{80, []string{"Agent", "ID", costTitle, "State", "Tools", "Out", "Total", "Share"}},              // loses Duration
		{60, []string{"Agent", "ID", "Out", "Total", "Share"}},                                           // the five DEVDESK-43 columns remain
	}
	for _, tt := range tests {
		for name, cfg := range map[string]*config.Config{"no prices": nil, "priced": cfgWith(t, pricesYAML)} {
			t.Run(name+"/"+strconv.Itoa(tt.width), func(t *testing.T) {
